suppressMessages({library(readr); library(dplyr)})
base <- "<repo>/benchmark/.cache/claude-code/gagliarducci-2022-gender-cooperation-congress/blind/2026-10-22-a/mount/gagliarducci_2022_gender_cooperation_congress/3 replication package/Data"
b <- read_csv(file.path(base, "AnalysisData/bills_analysis_101-111_replication.csv"), show_col_types=FALSE, guess_max=100000)
cat("dim", dim(b), "\n")
print(summary(b[, c("private","v2","sponsor_female","sponsor_party","sponsor_age","sponsor_tenure_run","sponsor_term_served","agestart","comc","comr","ivycoll","black","borninstate","mixed_gender_election","MV1_democrat","MV1_female","femaleXMV1_female","lag_demshare1","DSpndPct","lnpop","lnarea","lninc","pct_black","pct_urban","pct_for_born","pct_age_over65","numb_cosponsors","pct_cosponsors_opposite","minor")]))
for (v in c("private","v2","sponsor_party","sponsor_female","mixed_gender_election","comc","comr","sponsor_tenure_run")) {cat(v,"\n"); print(table(b[[v]], useNA="ifany"))}
occ <- b[, paste0("occ",0:6)]; print(colSums(occ, na.rm=TRUE)); print(table(rowSums(occ), useNA="ifany"))
print(table(b$sponsor_state_icpsr, useNA="ifany"))
cat("n distinct minor", n_distinct(b$minor), "\n")
hc <- grep("^house_", names(b), value=TRUE); cat("committee cols", length(hc), "\n"); print(table(rowSums(b[,hc]), useNA="ifany"))
print(head(as.data.frame(b[, c("v2","HRnumber","sponsor_name","sponsor_state_abbrev","sponsor_district")])))
b$sid <- paste(b$v2, b$sponsor_state_abbrev, b$sponsor_district, b$sponsor_name)
cat("sponsor-congress units", n_distinct(b$sid), " via state-district-v2", n_distinct(paste(b$v2,b$sponsor_state_abbrev,b$sponsor_district)), "\n")
cat("term_served table\n"); print(table(b$sponsor_term_served, useNA="ifany"))
cat("MV1_female among mixed\n"); print(summary(b$MV1_female[b$mixed_gender_election==1])); print(summary(b$MV1_female[b$mixed_gender_election==0]))
print(summary(b$MV1_democrat))
cat("pct_opp na:", sum(is.na(b$pct_cosponsors_opposite)), "\n")
print(table(b$sponsor_party, b$sponsor_female))
ctr <- c("sponsor_age","sponsor_tenure_run","comc","comr","black","ivycoll","borninstate","occ1","pct_black","pct_urban","pct_for_born","pct_age_over65","lninc","lnpop","lnarea","lag_demshare1","DSpndPct","MV1_democrat","minor","dwnom1")
print(sapply(b[ctr], function(x) sum(is.na(x))))
s <- read_csv(file.path(base, "IntermediateData/sponsors_analysis_101-111_clean.csv"), show_col_types=FALSE, n_max=5)
cat(names(s), "\n")
bc <- read_csv(file.path(base, "IntermediateData/bills_analysis_101-111_clean.csv"), show_col_types=FALSE, n_max=5)
cat(names(bc), "\n")
